\begin{itemize}
    \item When we write $a \lesssim b$, we mean that there exists some constant $c>0$ (independent of any involved parameter) such that $a \leq c b$;
    \item if $\alpha=(\alpha_1,\cdots,\alpha_n) \in \mathbb{N}^n$ is some multi-index, then we denote by 
    \[
    |\alpha|=\sum_{i=1}^{n}\alpha_i\,,
    \]
    the length of it;
    \item for $s>0$ and for suitable $f \in \mathcal{S}^{'}({\mathbb{G}})$, we have introduced the following norm
    \begin{equation}\label{def.Hs-norm}
    \|f\|_{H^{s}({\mathbb{G}})}:=\|f\|_{\dot{L}^{2}_{s}({\mathbb{G}})}+\|f\|_{L^2({\mathbb{G}})}\,;
    \end{equation}
    \item when regulisations of functions/distributions on ${\mathbb{G}}$ are considered, they must be regarded as arising  via  convolution  with  Friedrichs-mollifiers;  that is, $\psi$ is a Friedrichs-mollifier, if it is a compactly supported smooth function with $\int_{{\mathbb{G}}}\psi\,dx=1$. Then the regularising net is defined as
\begin{equation}\label{mol}
	\psi_{\epsilon}(x)=\omega(\epsilon)^{-Q}\psi(D_{\omega(\epsilon)^{-1}}(x))\,,\quad \epsilon \in (0,1]\,,
\end{equation}
where $\omega(\epsilon)$ is a positive function converging to zero as $\epsilon \rightarrow 0$ and $Q$ stands for the homogeneous dimension of ${\mathbb{G}}$.
\end{itemize}

\label{prop.pos.a}
Let $V \in L^{\infty}({\mathbb{G}})$, where $V \geq 0$, and suppose that $u_0 \in H^{\frac{ \nu}{2}}({\mathbb{G}})$. Then, there exists a unique solution $u \in C^{1}([0,T];L^2({\mathbb{G}}))\cap C([0,T];H^{\frac{ \nu}{2}}({\mathbb{G}}))$ to the Cauchy problem \eqref{heat.eq}, that satisfies the estimate 
	\begin{equation}\label{prop.pos.a.claim}
		\|u(t,\cdot)\|_{H^{\frac{ \nu}{2}}({\mathbb{G}})} \lesssim (1+\|V\|_{L^{\infty}({\mathbb{G}})}) \|u_0\|_{H^{\frac{ \nu}{2}}({\mathbb{G}})}\,,
		\end{equation}
		uniformly in $t \in [0,T]$.

Multiplying the equation \eqref{heat.eq} by $u_t$ and integrating over $\mathbb{G}$, we get
	\begin{equation*}\label{Re0,sch}
		\Re(\langle u_{t}(t,\cdot),u_t(t,\cdot)\rangle_{L^2(\mathbb{G})}+\langle \mathcal{R}u(t,\cdot),u_t(t,\cdot)\rangle_{L^2({\mathbb{G}})}+\langle V(\cdot)u(t,\cdot),u_t(t,\cdot) \rangle_{L^2({\mathbb{G}})})=0\,,
	\end{equation*}
for all $t \in [0,T]$, where $\Re$ stands for the real part of the above quantity. The above equation can be rewritten as
\[
\|u_t(t,\cdot)\|_{L^2({\mathbb{G}})}^{2}+\frac{1}{2}\partial_{t}\left[\| \sqrt{{\mathcal{R}}}u(t,\cdot)\|_{L^2({\mathbb{G}})}^{2}+  \| \sqrt{V}(\cdot)u(t,\cdot)\|_{L^2({\mathbb{G}})}^{2}\right]=0\,.
\]
We define the energy as 
\begin{equation*}\label{energy.est} E(t):=\|\sqrt{{\mathcal{R}}}u(t,\cdot)\|{^{2}_{L^2({\mathbb{G}})}}+\|\sqrt{V}(\cdot)u(t,\cdot)\|{^{2}_{L^2({\mathbb{G}})}}\,, 
\end{equation*}
which variation in time satisfies $\partial_{t}E(t)\leq 0$, and consequently  \begin{equation}\label{et=e0}E(t)\leq E(0)\,,\quad \text{for all}\quad t \in [0,T]\,.
\end{equation}
Straightforward computations give
\[
\|\sqrt{V}u_0\|{^{2}_{L^2({\mathbb{G}})}} \leq \|V\|_{L^{\infty}({\mathbb{G}})} \|u_0\|{^{2}_{L^2({\mathbb{G}})}}\,,
\]
so that equation \eqref{et=e0} can be rephrased as the uniform in time $t \in [0,T]$ estimates
\begin{equation}\label{pu.1.est}
\|\sqrt{V}u(t,\cdot)\|{^{2}_{L^2({\mathbb{G}})}} \lesssim \|\sqrt{{\mathcal{R}}}u_0\|{^{2}_{L^2({\mathbb{G}})}}+\|V\|_{L^{\infty}}\|u_0\|{^{2}_{L^2({\mathbb{G}})}}\,,
\end{equation}
and 
\begin{equation}\label{Ru.1.est}
\|\sqrt{{\mathcal{R}}}u(t,\cdot)\|{^{2}_{L^2({\mathbb{G}})}} \lesssim \|\sqrt{{\mathcal{R}}}u_0\|{^{2}_{L^2({\mathbb{G}})}}+\|V\|_{L^{\infty}}\|u_0\|{^{2}_{L^2({\mathbb{G}})}}\,.
\end{equation}
Recalling the definition of the sum of norms $H^s({\mathbb{G}})$ in \eqref{def.Hs-norm} we can estimate \eqref{pu.1.est} and \eqref{Ru.1.est} further by 
\begin{equation}\label{pu.2.est}
    \|\sqrt{V}u(t,\cdot)\|_{L^2({\mathbb{G}})} \lesssim \left( 1+\|V\|^{\frac{1}{2}}_{L^{\infty}({\mathbb{G}})}\right) \|u_0\|_{H^{\frac{ \nu}{2}}({\mathbb{G}})}\,,
\end{equation}
and
\begin{equation}\label{Ru.2.est}
    \|\sqrt{{\mathcal{R}}}u(t,\cdot)\|_{L^2({\mathbb{G}})}\lesssim \left( 1+\|V\|^{\frac{1}{2}}_{L^{\infty}({\mathbb{G}})}\right) \|u_0\|_{H^{\frac{ \nu}{2}}({\mathbb{G}})}\,,
\end{equation}
respectively.

To proceed we need to deal with the term $\|u(t,\cdot)\|_{L^2({\mathbb{G}})}$; let us rephrase the problem \eqref{heat.eq} as follows:
\begin{equation}\label{heat.eq2}
	\begin{cases}
		\partial_t u(t,x) +\mathcal{R}u(t,x)=f(t,x)\,,\quad (t,x)\in [0,T]\times \mathbb{G},\\
		u(0,x)=u_0(x),\,\\	
	\end{cases}       
\end{equation}
where we have set as a source term $f(t,x):=-V(x)u(t,x)$. Applying Duhamel's principle (see, e.g. \cite{Ev98}), we deduce that the solution to \eqref{heat.eq2} is given by 
\begin{equation}
	\label{sol.Duh}
	u(t,x)=(h_t \ast u_0)(x)+\int_{0}^{t
	}h_{t-s}\ast f_s(x)\,ds\,,
\end{equation}
where $f_s(\cdot)=f(s,\cdot)$, and $h_t(\cdot)=h(t,\cdot)$ with $h$ being the fundamental solution, or the heat kernel, associated to the Rockland operator ${\mathcal{R}}$. We recall (see, e.g. Theorem 4.2.7 \cite{FR16}) the following upper bound for the heat kernel norm
\[
\|h_t\|_{L^{1}({\mathbb{G}})}\leq 1\,.
\]
We take the $L^2({\mathbb{G}})$-norm of the expression on \eqref{sol.Duh}. Young's inequality implies for the convolution there
\begin{eqnarray}\label{lem1.last.est}
	\|u(t,\cdot)\|_{L^2({\mathbb{G}})} & \leq & \|h_t\|_{L^1({\mathbb{G}})}\|u_0\|_{L^2({\mathbb{G}})}+\int_{0}^{T} \|h_{t-s}\|_{L^1({\mathbb{G}})}\|f_s\|_{L^2({\mathbb{G}})}\,ds\nonumber\\
	& \leq & \|u_0\|_{L^2({\mathbb{G}})}+\int_{0}^{T}\|f_s\|_{L^2({\mathbb{G}})}\,ds\nonumber\\
	& \leq & \|u_0\|_{L^2({\mathbb{G}})}+\int_{0}^{T}\|V(\cdot)u(s,\cdot)\|_{L^2({\mathbb{G}})}\,ds\,.
\end{eqnarray}
Straightforward computations then give
\begin{equation}
    \label{prop1.l2-est}
    \|u(t,\cdot)\|_{L^2({\mathbb{G}})}\lesssim \|u_0\|_{H^{\frac{\nu}{2}}({\mathbb{G}})}+  \left(1+\|V\|_{L^{\infty}({\mathbb{G}})}\right)\|u_0\|_{H^{\frac{\nu}{2}}({\mathbb{G}})}\,.
\end{equation}
Putting together \eqref{Ru.2.est} and \eqref{prop1.l2-est} we obtain
\[
\|u(t,\cdot)\|_{L^2}^{2}+\|\sqrt{{\mathcal{R}}}u(t,\cdot)\|_{L^2}^{2} \lesssim (1+\|V\|_{L^\infty})\|u_0\|_{H^{\frac{\nu}{2}}}\,,
\]
as required, and the proof of Proposition \ref{prop.pos.a} is complete.

