We apply H\"older's inequality to the norm $\|\sqrt{V} u_0\|{^{2}_{L^2({\mathbb{G}})}}$ for $1<q,q^{'}<\infty$, so that
\begin{equation}
\label{prop2.Hold}
 \|\sqrt{V} u_0\|{^{2}_{L^2({\mathbb{G}})}} \leq \|V\|_{L^{q^{'}}({\mathbb{G}})}\|u_{0}\|^{2}_{L^{2q}({\mathbb{G}})}\,,
\end{equation}
where $(q,q^{'})$ are conjugate exponents. We use the embeddings \eqref{inclusions} for $u_0 \in H^{\frac{\nu}{2}}({\mathbb{G}})$, $b=\frac{ \nu}{2}$, $a=0$, and $q_0=\frac{2Q}{Q-\nu }$. This leads to the estimate 
\begin{equation}
\label{prop2.hold1}
\|u_0\|_{L^{q_{0}}({\mathbb{G}})} \lesssim \|\sqrt{{\mathcal{R}}}u_0\|_{L^2({\mathbb{G}})}<\infty\,.
\end{equation}
Putting together \eqref{prop2.Hold} for $q=\frac{q_0}{2}$, so that $q'=\frac{Q}{\nu}$, and \eqref{prop2.hold1} we obtain
\begin{eqnarray}
\label{emb}
\|\sqrt{V}u_0\|{^{2}_{L^2({\mathbb{G}})}} & \lesssim & \|V\|_{L^{\frac{Q}{\nu }}({\mathbb{G}})}\|\sqrt{{\mathcal{R}}}u_0\|_{L^2({\mathbb{G}})}^{2}\nonumber\\
& \leq & \|V\|_{L^{\frac{Q}{\nu }}({\mathbb{G}})} \|u_0\|_{H^{\frac{\nu}{2}}({\mathbb{G}})}^{2}\,.
\end{eqnarray}
Using the energy bounds \eqref{et=e0} from 
 Proposition \ref{prop.pos.a}, we have 
 \[
\|\sqrt{{\mathcal{R}}}u(t,\cdot)\|{^{2}_{L^2({\mathbb{G}})}}+\|\sqrt{V}u(t,\cdot)\|{^{2}_{L^2({\mathbb{G}})}}\leq \left(1+\|V\|_{L^{\frac{Q}{\nu }}({\mathbb{G}})}\right)\|u_0\|_{H^{\frac{ \nu}{2}}({\mathbb{G}})}^{2}\,,
\]
and the latter, if rephrased, leads to the estimate
\begin{equation}\label{EQ:prop.pos.b.est1}
    \|u(t,\cdot)\|_{\dot{L}^{2}_{\frac{\nu}{2}}({\mathbb{G}})} \leq \left(1+\|V\|_{L^{\frac{Q}{\nu }}({\mathbb{G}})}\right)^{\frac{1}{2}}\|u_0\|_{H^{\frac{ \nu}{2}}({\mathbb{G}})}\,.
\end{equation}
The estimate \eqref{lem1.last.est} for the $L^2$-norm of $u(t,\cdot)$ combined with the estimate \eqref{emb} with $V$ and $u(t,\cdot)$ in place of $\sqrt{V}$ and $u_0$, respectively, and inequality \eqref{EQ:prop.pos.b.est1} gives

\begin{eqnarray}\label{EQ:prop.pos.b.est2}
    \|u(t,\cdot)\|_{L^2({\mathbb{G}})}& \lesssim & \|u_0\|_{L^2({\mathbb{G}})}+\|V^2\|^{\frac{1}{2}}_{L^{\frac{Q}{\nu}}({\mathbb{G}})}\|u(t,\cdot)\|_{H^{\frac{\nu}{2}}({\mathbb{G}})}^{2}\nonumber\\
    & \leq & \|u_0\|_{H^{\frac{\nu}{2}}({\mathbb{G}})}+\|V\|_{L^{\frac{2Q}{\nu}}({\mathbb{G}})}\left(1+\|V\|_{L^{\frac{Q}{\nu }}({\mathbb{G}})}\right)^{\frac{1}{2}}\|u_0\|_{H^{\frac{ \nu}{2}}({\mathbb{G}})}\,.
\end{eqnarray}
 Putting together the estimate \eqref{EQ:prop.pos.b.est2} with the one in \eqref{EQ:prop.pos.b.est1} we get the requested estimate for the $H^{\frac{\nu}{2}}$-norm of $u(t,\cdot)$. The proof of Proposition \ref{prop.pos.b} is complete.

\label{prop.neg.a}
Let $u_0 \in L^2({\mathbb{G}})$ and suppose that $V\in L^\infty({\mathbb{G}})$ is a real function/distribution. Then, there exists a unique solution $u \in C([0,T];L^2({\mathbb{G}}))$ to the Cauchy problem \eqref{heat.eq} that satisfies the estimate 
\begin{equation}
    \label{prop.neg.a.claim}
    \|u(t,\cdot)\|_{L^2({\mathbb{G}})} \lesssim \exp( t\|V\|_{L^\infty({\mathbb{G}})})\|u_0\|_{L^2({\mathbb{G}})}\,,
\end{equation}
for all $t\in [0,T]$.

\label{def.vws.pos}
Let $V$ in \eqref{heat.eq} be non-negative. If there exists
\begin{itemize}
    \item a $L^\infty$-moderate, or (provided that $Q> \nu$) a $L^{\frac{Q}{\nu}}({\mathbb{G}})\cap L^{\frac{2Q}{\nu}}({\mathbb{G}})$-moderate approximation of $V$; 
    \item a $H^{\frac{\nu}{2}}({\mathbb{G}})$-moderate approximation of $u_0$;
    \item and the solution to the Cauchy problem \eqref{reg.heat.eq} $(u_\epsilon)_\epsilon$ is $C([0,T];H^{\frac{\nu}{2}}({\mathbb{G}}))$-moderate,
\end{itemize}
then, $(u_\epsilon)_\epsilon$ is said to be \textit{a very weak solution} to the Cauchy problem \eqref{heat.eq} in the case of a non-negative potential $V$.

\label{def.vws.any}
Let $V$ be any real function. If there exists
\begin{itemize}
    \item a $L^\infty$-moderate approximation of $V$;
    \item a $H^{\frac{\nu}{2}}({\mathbb{G}})$-moderate approximation of $u_0$;
    \item and the solution to the Cauchy problem \eqref{reg.heat.eq} $(u_\epsilon)_\epsilon$ is $C([0,T];L^2({\mathbb{G}}))$-moderate,
\end{itemize}
then, $(u_\epsilon)_\epsilon$ is said to be \textit{a very weak solution} to the Cauchy problem \eqref{heat.eq} in the case of a real potential $V$.

