\label{defn.uniq.heat.pos}
Let $V$ be non-negative. Let also $X$ and $Y$ be normed spaces of functions/distributions on ${\mathbb{G}}$.
We say that the Cauchy problem \eqref{heat.eq} has an \textit{$(X,Y)$-unique very weak solution}, if 
\begin{itemize}
    \item for all $X$-moderate nets
	$V_\epsilon, \tilde{V}_\epsilon,$ such that $(V_\epsilon-\tilde{V}_\epsilon)_\epsilon$ is $Y$-negligible; and
	\item for all $H^{\frac{ \nu}{2}}({\mathbb{G}})$-moderate regularisations $u_{0,\epsilon}$, $\tilde{u}_{0,\epsilon}$ such that $(u_{0,\epsilon}-\tilde{u}_{0,\epsilon})_\epsilon$ is $L^2({\mathbb{G}})$-negligible,
\end{itemize}
 the net $(u_\epsilon-\tilde{u}_\epsilon)$ is $L^2({\mathbb{G}})$-negligible, where $(u_\epsilon)_\epsilon$ and $(\tilde{u}_\epsilon)_\epsilon$ are the families of solutions corresponding to the $\epsilon$-parametrised problems \eqref{heat.reg.tild} and \eqref{heat.ret.notil}, respectively.

\label{defn/uniq.any}
[Uniqueness of the very weak solution, case $V \in \mathbb{R}$]
In the case of a real potential $V$ the definition is similar to Definition \ref{defn.uniq.heat.pos} but the moderateness assumption regarding the nets $u_{o,\epsilon}, \tilde{u}_{0,\epsilon}$ can be relaxed to being $L^2({\mathbb{G}})$-moderate.

\begin{itemize}
    \item Let $V$ be any function/distribution and the nets $V_\epsilon$ and $\tilde{V}_\epsilon$ to be defined as:
    \begin{equation}\label{mex}
        \begin{cases}
        V_\epsilon:=V \ast \psi_\epsilon\,, \text{where}\,  \psi_\epsilon:=\omega(\epsilon)^{-Q} \psi \circ D_{\omega(\epsilon)^{-1}}\nonumber\,,\\
        \tilde{V}_\epsilon=V_\epsilon+e^{-1/\epsilon}\,.
        \end{cases}
    \end{equation}
    \item For $V=\delta^2$ and nets $V_\epsilon$ and $\tilde{V}_\epsilon$ to be given by: 
    \begin{equation*}
        \begin{cases}
        V_\epsilon=\psi_{\epsilon}^{2}\\
         \tilde{V}_\epsilon=V_\epsilon+e^{-1/\epsilon}\,.
        \end{cases}
    \end{equation*}
\end{itemize}
The above considerations give rise to nets $V_\epsilon-\tilde{V}_\epsilon$ that are $L^\infty$-negligible, and therefore, satisfy the assumptions described in our definitions of uniqueness of the very weak solution to the Cauchy problem \eqref{heat.eq}.

\label{techn.lem}
Let $V$ be non-negative. Assume also that $u_0 \in L^2({\mathbb{G}})$ and $V \in L^{\infty}({\mathbb{G}})$, or $V \in L^{\frac{Q}{\nu}}({\mathbb{G}})\cap L^{\frac{2Q}{\nu}}({\mathbb{G}})$, provided that $Q> \nu$. Then, for the unique solution $u$ to the Cauchy problem \eqref{heat.eq} we have the energy estimate
\begin{equation}\label{en.est}
\|u(t,\cdot)\|_{L^2({\mathbb{G}})}\leq \|u_0\|_{L^2({\mathbb{G}})}\,,
\end{equation}
for all $t \in [0,T]$.

\label{thm.un.pos.1}
Let $V$ be non-negative. Let also $u_0 \in H^{\frac{\nu}{2}}({\mathbb{G}})\cup \mathcal{E}'({\mathbb{G}})$. The following statements hold true:
\begin{itemize}
    \item If $V \in L^{\infty}({\mathbb{G}})\cup \mathcal{E}'({\mathbb{G}})$, then the very weak solution to the Cauchy problem \eqref{heat.eq} is $(L^{\infty}({\mathbb{G}}),L^\infty ({\mathbb{G}}))$-unique;
    \item if $Q > \nu$ and $V \in L^{\infty}({\mathbb{G}})\cup \mathcal{E}'({\mathbb{G}})$, then the very weak solution to the Cauchy problem \eqref{heat.eq} is $(L^{\frac{Q}{\nu}}({\mathbb{G}})\cap L^{\frac{2Q}{ \nu}}({\mathbb{G}}), L^\infty ({\mathbb{G}}))$-unique.
\end{itemize}

We denote by $u_\epsilon$ and $\tilde{u}_\epsilon$ the families of solutions to the Cauchy problems \eqref{heat.ret.notil} and \eqref{heat.reg.tild}, respectively. Setting $U_\epsilon$ to be the difference of these nets $U_\epsilon:=u_\epsilon(t,\cdot)-\tilde{u}_\epsilon(t,\cdot)$, then $U_\epsilon$ solves
\begin{eqnarray}
\label{forU1}
\begin{cases}
\partial_t U_\epsilon(t,x)+{\mathcal{R}} U_\epsilon(t,x)+V_\epsilon(x)U_\epsilon(t,x)=f_\epsilon(t,x)\,,\quad (t,x)\in [0,T] \times {\mathbb{G}}\,,\\
U_\epsilon(0,x)=(u_{0,\epsilon}-\tilde{u}_{0,\epsilon})(x)\,,\quad x \in {\mathbb{G}}\,,
\end{cases}
\end{eqnarray}
where we set $f_\epsilon(t,x):=(\tilde{V}_\epsilon(x)-V_\epsilon(x))\tilde{u}_\epsilon(t,x)$ for the mass term to the inhomogeneous Cauchy problem \eqref{forU1}.

We aim to express the solution to \eqref{forU1} in terms of the solutions to the corresponding homogeneous problems: fix $\sigma \in [0,T]$, and let $W_\epsilon(t,x)$ and $\tilde{U}_\epsilon(t,x;\sigma)$ being the solutions to following the Cauchy problems
\begin{equation*}
\begin{cases*}
	\partial_{t}W_\epsilon(t, x)+{\mathcal{R}} W_\epsilon(t, x)+V(x)_\epsilon(x) W_\epsilon(t, x)=0\,,\quad\text{in}\, [0,T] \times {\mathbb{G}},\\
	W_\epsilon(t, x)=(u_{0,\epsilon}-\tilde{u}_{0,\epsilon})(x)\,\quad \text{on}\,\{t=0\}\times {\mathbb{G}}\,,
\end{cases*}
\end{equation*}
and
\begin{equation*}\label{hom.Ve}
\begin{cases*}
	\partial_{t}\tilde{U}_\epsilon(t, x;\sigma)+{\mathcal{R}} \tilde{U}_\epsilon(t, x;\sigma)+V_\epsilon(x) \tilde{U}_\epsilon(t, x;\sigma)=0\,,\quad\text{in}\, (\sigma,T] \times {\mathbb{G}},\\
	\tilde{U}_\epsilon(t, x;\sigma)=f_\epsilon(\sigma,x)\,\quad \text{on}\,\{t=\sigma\}\times {\mathbb{G}}\,.
\end{cases*}
\end{equation*}
Thus, with the above considerations, we can write as an application of Duhamel's principle:
\begin{equation*}\label{duh.prin}
U_\epsilon(t,x)=W_\epsilon(t,x)+\int_{0}^{t}\tilde{U}_\epsilon(t-\sigma,x;\sigma)\,d\sigma\,.
\end{equation*}
Passing to the $L^2$-norm of the latter expression we get
\[
	\|U_\epsilon(t,\cdot)\|_{L^2({\mathbb{G}})} \leq \|W_\epsilon(t,\cdot)\|_{L^2({\mathbb{G}})}+ \left\| \int_{0}^{t}\tilde{U}_\epsilon(t-\sigma,\cdot;\sigma)\,d\sigma \right \|_{L^2({\mathbb{G}})}\,.
	\]
	An application of Minkowski's integral inequality, combined with the energy upper bound \eqref{en.est} for both solutions $W_\epsilon$ and $\tilde{U}_\epsilon$ to the Cauchy problems as above, allow to estimate $\|U_\epsilon(t,\cdot)\|_{L^2}$  further as given below:
	\begin{eqnarray}\label{mink}
\|U_\epsilon(t,\cdot)\|_{L^2({\mathbb{G}})} & \leq & \|W_\epsilon(t,\cdot)\|_{L^2({\mathbb{G}})}+\int_{0}^{T}\|\tilde{U}_\epsilon(t-\sigma,\cdot;\sigma)\|_{L^2({\mathbb{G}})}\,d\sigma\nonumber\\
& \leq & \|u_{0,\epsilon}-\tilde{u}_{0,\epsilon}\|_{L^2({\mathbb{G}})}+\int_{0}^{T}\|f_\epsilon(\sigma,\cdot)\|_{L^2({\mathbb{G}})}\,d\sigma\,.
\end{eqnarray}
Since
\[
\|f_\epsilon(\sigma,\cdot)\|_{L^2({\mathbb{G}})}\leq \|\tilde{V}_\epsilon-V_\epsilon\|_{L^\infty({\mathbb{G}})}\|\tilde{u}_\epsilon(\sigma,\cdot)\|_{L^2({\mathbb{G}})}\,,
\]
using \eqref{mink} we obtain 
\[
\|\tilde{u}_\epsilon(\sigma,\cdot)\|_{L^2({\mathbb{G}})} \leq \|u_{0,\epsilon}-\tilde{u}_{0,\epsilon}\|_{L^2({\mathbb{G}})}\int_{0}^{T} \|\tilde{u}_\epsilon(\sigma,\cdot)\|_{L^2({\mathbb{G}})}\,d\sigma\,.
\]
Finally, taking into account the negligibility of the nets $u_{0,\epsilon}-\tilde{u}_{0,\epsilon}$ and $\tilde{V}_\epsilon-V_\epsilon$ we get
\[
\|U_\epsilon(t,\cdot)\|_{L^2({\mathbb{G}})} \lesssim \omega_1(\epsilon)^{N}+\omega_2(\epsilon)^{\tilde{N}}  \int_{0}^{T}\omega_3(\epsilon)^{-N_1}\,d\sigma  \,,
\]
for some $N_1 \in \mathbb{N}$, and for all $N,\tilde{N} \in \mathbb{N}$, since $\tilde{u}_\epsilon$ is $H^{\frac{\nu}{2}}({\mathbb{G}})$-moderate, and so also $L^2({\mathbb{G}})$-moderate. The last estimate holds true uniformly in $t$, and this completes the proof of Theorem \ref{thm.un.pos.1}.

